    private async Task VerifyModels(CatalogResult catalog)
    {
        static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        var item=catalog.Items.Single(i=>i.Id==22419);var asset=await ItemModelAssets.Shared.Resolve(item.Id);Assert(asset.Models.Order().SequenceEqual(new[]{143286,143585})&&asset.Textures.Contains(143392),"Dreadnaught shoulders resolve their actual two meshes and skin from server appearance mappings");
        var bitmap=ModelTexture.Decode(await ItemModelAssets.Shared.Read(143392));var pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(pixels,bitmap.PixelWidth*4,0);int blue=Enumerable.Range(0,pixels.Length/4).Count(n=>pixels[n*4+3]>100&&pixels[n*4]>pixels[n*4+2]+15);Assert(blue>20,"Dreadnaught skin contains its blue color data");
        bool corrupt=false;try{ModelTexture.Decode(new byte[12]);}catch(InvalidDataException){corrupt=true;}Assert(corrupt,"Truncated texture input is rejected");
        byte[] Blp(int encoding,int depth,int alpha,int width,int height,int offset,byte[] mip){var data=new byte[offset+mip.Length];System.Text.Encoding.ASCII.GetBytes("BLP2").CopyTo(data,0);data[8]=(byte)encoding;data[9]=(byte)depth;data[10]=(byte)alpha;BitConverter.GetBytes(width).CopyTo(data,12);BitConverter.GetBytes(height).CopyTo(data,16);BitConverter.GetBytes(offset).CopyTo(data,20);BitConverter.GetBytes(mip.Length).CopyTo(data,84);mip.CopyTo(data,offset);return data;}
        byte[] Pixels(byte[] data){var b=ModelTexture.Decode(data);var p=new byte[b.PixelWidth*b.PixelHeight*4];b.CopyPixels(p,b.PixelWidth*4,0);return p;}
        var dxt1=Pixels(Blp(2,1,0,4,4,148,[0,248,224,7,228,228,228,228]));Assert(dxt1[2]==255&&dxt1[0]==0&&dxt1[3]==255&&dxt1[5]==255,"DXT1 RGB565 colors and block indices decode correctly");var transparent=Pixels(Blp(2,1,0,4,4,148,[0,0,255,255,255,255,255,255]));Assert(transparent[3]==0,"DXT1 transparent palette entry is preserved");var dxt3=Pixels(Blp(2,4,1,4,4,148,[33,0,0,0,0,0,0,0,0,248,0,0,0,0,0,0]));Assert(dxt3[3]==17&&dxt3[7]==34,"DXT3 four-bit alpha decoding");var dxt5=Pixels(Blp(2,8,7,4,4,148,[255,0,8,0,0,0,0,0,0,248,0,0,0,0,0,0]));Assert(dxt5[3]==255&&dxt5[7]==0,"DXT5 alpha endpoints and indices decode correctly");var palette=Blp(1,8,0,1,1,1172,[3,127]);palette[160]=4;palette[161]=5;palette[162]=6;Assert(Pixels(palette).SequenceEqual(new byte[]{4,5,6,127}),"Paletted BLP color and alpha decoding");Assert(Pixels(Blp(3,8,0,1,1,148,[1,2,3,4])).SequenceEqual(new byte[]{1,2,3,4}),"BGRA BLP decoding");
        bool switched=false;try{await ItemModelAssets.Shared.Read(143286,"other-client");}catch(InvalidOperationException){switched=true;}Assert(switched,"A changed client cannot mix assets into an older load");
        var weaponAppearance=await ItemModelAssets.Shared.Resolve(19019);var weapon=await StaticItemModel.Load(ItemModelAssets.Shared,weaponAppearance.Parts.First());Assert(weapon.Triangles>0&&weapon.Textures>0&&weapon.Model.IsFrozen,"A textured weapon mesh also loads as a frozen model");
        int? duplicate=null;foreach(var op in (await ContentEditing.ListAsync()).Where(o=>o.Kind=="NewSet"&&o.Active)){var scope=JsonSerializer.Deserialize<ContentScope>(op.Scope);duplicate=scope?.Creation?.Sources?.FirstOrDefault(p=>p.Value==22419&&catalog.Items.Any(i=>i.Id==p.Key)).Key;if(duplicate>0)break;}if(duplicate>0){var copy=await ItemModelAssets.Shared.Resolve(duplicate.Value);Assert(copy.Models.SequenceEqual(asset.Models)&&copy.Textures.SequenceEqual(asset.Textures),"A custom duplicated shoulder resolves through its own server mapping to its base appearance");}
        var view=new ItemModelView(enlarged:true);var window=new Window{Title="Textured Dreadnaught Pauldrons",Content=view,Width=1000,Height=900,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};window.Show();view.Bind(item);await view.Loading;Assert(view.LoadedItem==item.Id&&view.TriangleCount>0&&view.TextureCount>=2,"Both shoulder parts render with textures");await RenderEditorWindow(window,"dreadnaught-model-preview");IEnumerable<Button> Buttons(DependencyObject root){foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){if(child is Button button)yield return button;foreach(var nested in Buttons(child))yield return nested;}}Assert(Buttons(view).Single(b=>b.Content?.ToString()=="Larger view…").Visibility==Visibility.Collapsed,"Enlarged view cannot spawn another enlarged window");view.Rotate(0,0,0);view.Drag(new Point(600,300),new Point(700,440),new Size(1000,800),true);Assert(Math.Abs(view.Angles.X)>1&&Math.Abs(view.Angles.Y)>1&&Math.Abs(view.Angles.Z)>1,"Shift-trackball rotation changes all three axes and synchronizes the sliders");view.Rotate(110,-65,80);Assert(view.Angles==(110d,-65d,80d),"X Y and Z rotations are independent");await RenderEditorWindow(window,"dreadnaught-model-rotated-preview");view.Bind(null);Assert(view.LoadedItem==0,"Clearing selection clears the old geometry");view.Bind(item);view.Bind(null);await view.Loading;await Task.Delay(150);Assert(view.LoadedItem==0,"An older asynchronous item load cannot overwrite a cleared selection");window.Close();
        ItemsGrid.SelectedItem=item;ItemsGrid.ScrollIntoView(item);CatalogPreviewTabs.SelectedIndex=1;await itemModel.Loading;Assert(itemModel.LoadedItem==22419,"Catalog 3D tab follows the selected item");await RenderEditorWindow(this,"catalog-model-preview");Assert(itemModel.ViewportHeight>=80,"Catalog model viewport remains visible with expanded filters");CatalogPreviewTabs.SelectedIndex=0;
        await File.WriteAllTextAsync("artifacts/model-viewer-verification.json",JsonSerializer.Serialize(new{item=item.Id,asset.Appearance,asset.Display,models=asset.Models,textures=asset.Textures,client=ItemModelAssets.Shared.Version,textureWidth=bitmap.PixelWidth,textureHeight=bitmap.PixelHeight,bluePixels=blue,duplicateShoulder=duplicate,weaponTriangles=weapon.Triangles,checks="Server appearance mapping; actual CASC meshes and BLP skin; both shoulders; textured weapon; independent XYZ rotation; stale load and mixed-client rejection; visible catalog viewport; custom duplicate mapping when available; malformed texture rejection; DXT1/3/5, paletted and BGRA golden pixels; no game writes"},new JsonSerializerOptions{WriteIndented=true}));Close();
    }
